/* Small dependency-free OOXML workbook writer. Cell text is never a formula. */
const xmlEscape=v=>String(v??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'');
function excelColumn(index){let s='';for(let n=index+1;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s}
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^(c&1?0xedb88320:0)}return (c^0xffffffff)>>>0}
function zipStore(files){let enc=new TextEncoder(),parts=[],directory=[],offset=0;const header=(size)=>new Uint8Array(size);for(const [name,text] of Object.entries(files)){let filename=enc.encode(name),data=enc.encode(text),crc=crc32(data),h=header(30),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,filename.length,true);parts.push(h,filename,data);let d=header(46),dv=new DataView(d.buffer);dv.setUint32(0,0x02014b50,true);dv.setUint16(4,20,true);dv.setUint16(6,20,true);dv.setUint16(8,0x800,true);dv.setUint16(14,33,true);dv.setUint32(16,crc,true);dv.setUint32(20,data.length,true);dv.setUint32(24,data.length,true);dv.setUint16(28,filename.length,true);dv.setUint32(42,offset,true);directory.push(d,filename);offset+=h.length+filename.length+data.length}let directorySize=directory.reduce((s,p)=>s+p.length,0),end=header(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,Object.keys(files).length,true);e.setUint16(10,Object.keys(files).length,true);e.setUint32(12,directorySize,true);e.setUint32(16,offset,true);return new Blob([...parts,...directory,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
function workbookFile(rows,title='Report'){let keys=[...new Set(rows.flatMap(r=>Object.keys(r)))],values=[keys,...rows.map(r=>keys.map(k=>r[k]??''))];let xml='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+values.map((row,i)=>`<row r="${i+1}">${row.map((val,j)=>{let ref=excelColumn(j)+(i+1);return typeof val==='number'&&Number.isFinite(val)?`<c r="${ref}"><v>${val}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xmlEscape(typeof val==='object'?JSON.stringify(val):val)}</t></is></c>`}).join('')}</row>`).join('')+'</sheetData></worksheet>';return zipStore({'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>','_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>','xl/workbook.xml':`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${xmlEscape(title.replace(/[\\/?*\[\]:]/g,' ').slice(0,31))}" sheetId="1" r:id="rId1"/></sheets></workbook>`,'xl/_rels/workbook.xml.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>','xl/worksheets/sheet1.xml':xml})}
function exportExcel(kind){let rows=kind==='bookings'?parityBookings():kind==='renewals'?renewalRows():kind==='leads'?filteredLeads():kind==='contacts'?contactRows():payoutRows();if(!rows.length)return toast('No records to export');let plain=rows.map(r=>Object.fromEntries(Object.entries(r).filter(([,v])=>typeof v!=='object')));fileDownload('sigma0nine-'+kind+'.xlsx',workbookFile(plain,kind),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Excel workbook downloaded')}
